import { hotTicketsMock } from "../mock/alerts";

export const fetchHotTickets = (): Promise<number[]> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      const shuffled = [...hotTicketsMock].sort(() => 0.5 - Math.random());
      resolve(shuffled.slice(0, 3));
    }, 600);
  });
};
